import { type ChangeEvent, type ReactElement, type Ref } from 'react';
import { type CheckboxProps } from '../core/checkbox-props.js';
import toChecked from '../core/to-checked.js';
import useIndeterminate from '../core/use-indeterminate.js';
import classes from './checkbox.module.scss';

/**
 * A checkbox is a checkable input that has three possible values: true,
 * false, or 'mixed'. If the checkbox controls a group of elements have a
 * mixture of checked and unchecked values, use 'mixed'.
 * @see {@link https://w3c.github.io/aria/#checkbox | WAI-ARIA `checkbox` role}
 */
export default function Checkbox({
  disabled = false,
  label,
  onCheck,
  onUncheck,
  readOnly = false,
  required = false,
  value,
}: CheckboxProps): ReactElement {
  const checked: boolean | undefined = toChecked(value);

  const ref: Ref<HTMLInputElement> = useIndeterminate(value);

  const handleChange = (ev: ChangeEvent<HTMLInputElement>): void => {
    if (ev.currentTarget.checked) {
      onCheck();
    } else {
      onUncheck();
    }
  };

  return (
    <label className={classes['root']}>
      <input
        /**
         * Due to the strong native semantics of HTML's native checkbox, use
         * its `checked` attribute and `indeterminate` IDL attribute to specify
         * its checked and mixed states, respectively.
         */
        aria-checked={undefined}
        aria-disabled={disabled}
        aria-readonly={readOnly}
        aria-required={required}
        checked={checked}
        className={classes['checkbox']}
        disabled={disabled}
        onChange={handleChange}
        readOnly={readOnly}
        required={required}
        ref={ref}
        role="checkbox"
        type="checkbox"
      />
      <span aria-hidden="true" className={classes['art']}>
        <span className={classes['shadow']} />
        <span className={classes['tile']}>
          <span className={classes['mark']} />
        </span>
        <span className={classes['sun']} />
        <span className={classes['triangle']} />
        <span className={classes['sprinkles']} />
      </span>
      <span className={classes['label']}>{label}</span>
    </label>
  );
}
